using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;
namespace EarthUnscripted.Editor
{
 public static class WorldMeshAuthoringChecks
 {
  [Serializable]public sealed class Report{public string status,sourceDigest;public int checks;public string scope="Actual canonical raw source accounting only; no mesh/terrain/full-world admission or engine activation";}
  static void Check(Report r,bool okay,string why){if(!okay)throw new Exception("AUTHORING AUDIT FAIL "+why);r.checks++;}
  static void Reject(Report r,Action action,string why){try{action();}catch(InvalidDataException){r.checks++;return;}throw new Exception("AUTHORING AUDIT accepted "+why);}
  static GeoRoad[] Roads(World13Document d){var rows=d.roadAuthority.sourceRoads.ToDictionary(r=>r.roadId,r=>r.nodeIds);return d.geography.roads.Select(r=>{var c=WorldFieldJson.Clone(r);c.sourceNodeIds=(string[])rows[r.id].Clone();return c;}).ToArray();}
  public static Report Execute(string output)
  {
   if(Directory.Exists(output)||!output.StartsWith("/private/tmp/rr019-world-mesh-accounting-",StringComparison.Ordinal))throw new Exception("Fresh owned evidence directory required");Directory.CreateDirectory(output);var r=new Report();try{
    var input=ReviewedCanonicalRaw13Input.CaptureReviewedSnapshot("/private/tmp/rr019-integration-drafts/ActualPantside");var raw=CanonicalRaw13Codec.Read(input,input.CopyDocumentBytes());var d=WorldFieldJson.Read<World13Document>(new System.Text.UTF8Encoding(false,true).GetString(raw.Write()));var roads=Roads(d);var rails=d.geography.railways;r.sourceDigest=d.roadAuthority.sourceDigest;
    var audit=WorldMeshAuthoringAudit.VerifyAccountingOnly(raw,roads,rails,Array.Empty<WorldAuthoringChange>());Check(r,audit.AddedRoads==0&&audit.ChangedRails==0&&!audit.GeometryAdmitted&&audit.OriginalSourceDigest==r.sourceDigest,"unchanged source accounted without geometry permission");
    {var changed=Roads(d);changed[0].width+=.1f;Reject(r,()=>WorldMeshAuthoringAudit.VerifyAccountingOnly(raw,changed,rails,Array.Empty<WorldAuthoringChange>()),"raw width mutation");}
    {var changed=Roads(d);changed[0].points[0].y+=.1f;Reject(r,()=>WorldMeshAuthoringAudit.VerifyAccountingOnly(raw,changed,rails,Array.Empty<WorldAuthoringChange>()),"raw source elevation mutation instead of controls");}
    Reject(r,()=>WorldMeshAuthoringAudit.VerifyAccountingOnly(raw,roads.Skip(1).ToArray(),rails,Array.Empty<WorldAuthoringChange>()),"source road removal");
    var parent=roads[0];var connector=new GeoRoad{id="fictional-service-approach",name="Original test connector",kind="service",start="authored-entry",end="authored-pad",width=5,limit=15,points=new[]{parent.points[0],parent.points[0]+new Vector3(20,0,20)},sourceNodeIds=new[]{"authored-entry","authored-pad"}};var augmented=roads.Concat(new[]{connector}).ToArray();var change=new WorldAuthoringChange{entity="road",id=connector.id,kind="service",originalSHA="",authoredSHA=RoadSourceIdentity.Compute(new[]{connector}),policyPin=new string('c',64),parentRoadId=parent.id,parentSourceS=0};
    Reject(r,()=>WorldMeshAuthoringAudit.VerifyAccountingOnly(raw,augmented,rails,Array.Empty<WorldAuthoringChange>()),"unaccounted garage road");var declared=WorldMeshAuthoringAudit.VerifyAccountingOnly(raw,augmented,rails,new[]{change});Check(r,declared.AddedRoads==1&&declared.AuthoredSourceDigest!=declared.OriginalSourceDigest&&!declared.GeometryAdmitted,"explicit service accounting preserves original identity and cannot admit geometry");
    foreach(string mutation in new[]{"hash","parent","station","policy","kind","origin"}){var c=WorldFieldJson.Clone(change);if(mutation=="hash")c.authoredSHA=new string('0',64);if(mutation=="parent")c.parentRoadId="absent";if(mutation=="station")c.parentSourceS=-1;if(mutation=="policy")c.policyPin="caller says true";if(mutation=="kind")c.kind="road";if(mutation=="origin")c.originalSHA=new string('a',64);Reject(r,()=>WorldMeshAuthoringAudit.VerifyAccountingOnly(raw,augmented,rails,new[]{c}),"invalid declared service "+mutation);}
    Reject(r,()=>WorldMeshAuthoringAudit.VerifyAccountingOnly(raw,roads,rails,new[]{change}),"unused change declaration");
    Check(r,rails.Length>0,"actual raw rail source available");var changedRails=rails.Select(x=>WorldFieldJson.Clone(x)).ToArray();changedRails[0].points[0].y+=.45f;Reject(r,()=>WorldMeshAuthoringAudit.VerifyAccountingOnly(raw,roads,changedRails,Array.Empty<WorldAuthoringChange>()),"unaccounted rail preparation");
    string Before(GeoRailway x)=>World13DocumentCodec.Hash(CanonicalGeography13.WriteBytes(x));var railChange=new WorldAuthoringChange{entity="rail",id=rails[0].id,kind="rail-profile",originalSHA=Before(rails[0]),authoredSHA=Before(changedRails[0]),policyPin=new string('d',64)};var railAudit=WorldMeshAuthoringAudit.VerifyAccountingOnly(raw,roads,changedRails,new[]{railChange});Check(r,railAudit.ChangedRails==1&&!railAudit.GeometryAdmitted,"declared Y-only rail solve accounted without clearance claim");changedRails[0].points[0].x+=1;railChange.authoredSHA=Before(changedRails[0]);Reject(r,()=>WorldMeshAuthoringAudit.VerifyAccountingOnly(raw,roads,changedRails,new[]{railChange}),"declared rail hash cannot grant source XZ mutation");
    Check(r,raw.Write().SequenceEqual(input.CopyDocumentBytes()),"all audit failures preserve raw owner bytes");r.status="PASS";return r;
   }catch(Exception e){r.status="FAIL";File.WriteAllText(Path.Combine(output,"failure.txt"),e.ToString());throw;}finally{File.WriteAllText(Path.Combine(output,"receipt.json"),CanonicalGeography13.Write(r,true));}
  }
 }
 public static class WorldMeshAuthoringVerification{public static void Run(){int code=1;try{if(Application.isPlaying||UnityEngine.Object.FindAnyObjectByType<GameSession>())throw new Exception("Isolated accounting proof required");var r=WorldMeshAuthoringChecks.Execute("/private/tmp/rr019-world-mesh-accounting-unity-"+DateTime.UtcNow.Ticks);Debug.Log("WORLD MESH ACCOUNTING PASS "+r.checks);code=0;}catch(Exception e){Debug.LogException(e);}EditorApplication.Exit(code);}}
}
